sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?category WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?component .
  ?component skos:broader* ?category .
  FILTER NOT EXISTS { ?category skos:broader ?parent . }
}
ORDER BY ?category

SELECT ?campaign ?potentiallyAffected WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "26V430000" ;
            rc:potentiallyAffected ?potentiallyAffected .
}

SELECT DISTINCT ?campaign ?campaignNumber ?makeName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:doNotDrive true ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER (UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaign ?campaignNumber ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name "PALISADE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER (YEAR(?date) = 2024)
}
ORDER BY ?date

SELECT DISTINCT ?makeName ?modelName WHERE {
  ?camp rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName .
  OPTIONAL {
    ?model rc:ofMake ?make .
    ?make rc:name ?makeName .
  }
}
ORDER BY ?makeName ?modelName

SELECT ?component ?name (COUNT(DISTINCT ?campaign) AS ?campaignCount) WHERE {
  # "Detailed" = a sub-category with a parent (skos:broader), not a top-level component.
  ?component a rc:Component ;
             rc:name ?name ;
             skos:broader ?parent .
  # Campaigns that affect this component and a Hyundai or Kia vehicle variant.
  ?campaign rc:affectsComponent ?component ;
            rc:affects/rc:ofModel/rc:ofMake/rc:name ?make .
  FILTER(?make IN ("HYUNDAI", "KIA"))
  # The component must appear in both Hyundai and Kia recalls.
  FILTER EXISTS {
    ?hCampaign rc:affectsComponent ?component ;
               rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?kCampaign rc:affectsComponent ?component ;
               rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" .
  }
}
GROUP BY ?component ?name
ORDER BY DESC(?campaignCount)
LIMIT 1

SELECT DISTINCT ?campaign ?campaignNumber WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:modelYear ?year ;
           rc:ofModel ?model .
  FILTER(STR(?year) = "2021")
  ?model rc:name "SANTA FE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?genesisModel ?compName WHERE {
  ?tellCamp rc:affects ?tellVariant ;
            rc:affectsComponent ?component .
  ?tellVariant rc:ofModel ?tellModel .
  ?tellModel rc:name "TELLURIDE" ;
             rc:ofMake ?kiaMake .
  ?kiaMake rc:name "KIA" .

  ?genCamp rc:affects ?genVariant ;
           rc:affectsComponent ?component .
  ?genVariant rc:ofModel ?genModel .
  ?genModel rc:name ?genesisModel ;
            rc:ofMake ?genMake .
  ?genMake rc:name "GENESIS" .

  ?component rc:name ?compName .
}
ORDER BY ?compName ?genesisModel

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(UCASE(?makeName) IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(STRSTARTS(STR(?d), "2023-"))
}

SELECT ?top ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?rc rc:affectsComponent ?comp ;
      rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?anyParent }
  OPTIONAL { ?top rc:name ?topName }
}
GROUP BY ?top ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT ?campaign ?campaignNumber ?potentiallyAffected WHERE {
  ?campaign rc:parkOutside true ;
            rc:potentiallyAffected ?potentiallyAffected ;
            rc:campaignNumber ?campaignNumber .
}
ORDER BY DESC(?potentiallyAffected)
LIMIT 1

SELECT ?top ?topName (COUNT(DISTINCT ?camp) AS ?campaigns) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affects ?v ;
        rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name "GENESIS" .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  OPTIONAL { ?top rc:name ?topName }
}
GROUP BY ?top ?topName
ORDER BY DESC(?campaigns)

SELECT (COUNT(DISTINCT ?year) AS ?modelYearCount) WHERE {
  ?make a rc:Make ;
        rc:name "HYUNDAI" .
  ?model a rc:VehicleModel ;
         rc:ofMake ?make ;
         rc:name "SONATA" .
  ?variant a rc:VehicleVariant ;
           rc:ofModel ?model ;
           rc:modelYear ?year .
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?n)
LIMIT 1

SELECT DISTINCT ?campaign ?campaignNumber ?componentName ?defectSummary
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:defectSummary ?defectSummary .
  OPTIONAL {
    ?campaign rc:affectsComponent ?component .
    ?component rc:name ?componentName .
  }
  OPTIONAL { ?campaign rc:rootCause ?rootCause . }
  BIND(CONCAT(COALESCE(?defectSummary, ""), " ", COALESCE(?componentName, ""), " ", COALESCE(?rootCause, "")) AS ?text)
  FILTER(CONTAINS(UCASE(?text), "HYDROGEN"))
  FILTER(CONTAINS(UCASE(?text), "LEAK") || CONTAINS(UCASE(?text), "DETECT") || CONTAINS(UCASE(?text), "SENSOR"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaign ?campaignNumber ?componentName ?defectSummary WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?campaign rc:defectSummary ?defectSummary . }
  OPTIONAL {
    ?campaign rc:affectsComponent ?comp .
    ?comp rc:name ?componentName .
  }
  FILTER (
    (BOUND(?componentName) && REGEX(?componentName, "CHARG", "i")) ||
    (BOUND(?defectSummary) && REGEX(?defectSummary, "ICCU|integrated charg|charging control|12[ -]?V(OLT)?.*batter", "i"))
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaign ?campaignNumber ?component ?defectSummary WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:defectSummary ?defectSummary .
  OPTIONAL { ?campaign rc:affectsComponent ?c . ?c rc:name ?component . }
  OPTIONAL { ?campaign rc:rootCause ?rootCause . }
  BIND(CONCAT(STR(?defectSummary), " ", COALESCE(STR(?rootCause), ""), " ", COALESCE(STR(?component), "")) AS ?text)
  FILTER(REGEX(?text, "water|moisture|humid|condensation", "i"))
  FILTER(REGEX(?text, "tow|trailer|hitch", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaign ?campaignNumber WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber .
  {
    ?campaign rc:defectSummary|rc:rootCause|rc:consequenceSummary|rc:correctiveSummary ?text .
    FILTER(REGEX(?text, "(connecting|con)[ -]?rod[^.]*bearing|rod bearing", "i"))
  }
  UNION
  {
    ?campaign rc:affectsComponent ?component .
    ?component rc:name ?compName .
    FILTER(REGEX(?compName, "connecting rod|rod bearing", "i"))
  }
}
ORDER BY ?campaignNumber
